begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values ('a2000000-0000-4000-8000-000000000001','branded-owner@example.test',now()),('a2000000-0000-4000-8000-000000000002','branded-other@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"a2000000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Branded test','branded-test',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','branded@example.test','')::text,true);
select set_config('test.message',gen_random_uuid()::text,true);
select queue_seller_communication(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,current_setting('test.seller')::uuid,'message','seller.welcome','v3','sv','Welcome to Synthetic store','Frozen welcome','none',null);
select throws_like($$select prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'other@example.test')$$,'%REQUEST_CONFLICT%','recipient is frozen');
select set_config('test.ticket',prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'branded@example.test'),true);
select matches(current_setting('test.ticket'),'^[a-f0-9]{64}$','unpredictable 256-bit capability');
select isnt((select activation_email_ticket_hash from seller_communications where id=current_setting('test.message')::uuid),current_setting('test.ticket'),'only digest is stored');
select is(prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'branded@example.test'),null::text,'replay never issues another capability');
select throws_like($$update seller_communications set activation_email_consumed_at=null where id=current_setting('test.message')::uuid$$,'%permission denied%','staff cannot reset consumption');
set local "request.jwt.claims"='{"sub":"a2000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_like($$select prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'branded@example.test')$$,'%FORBIDDEN%','other tenants cannot prepare');
set local role anon;
select throws_like($$select prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.message')::uuid,'branded@example.test')$$,'%permission denied%','anonymous preparation forbidden');
select is(consume_seller_activation_email(null,'branded@example.test'),null::jsonb,'missing capability grants nothing');
select is(consume_seller_activation_email(repeat('0',64),'branded@example.test'),null::jsonb,'unknown capability grants nothing');
select is(consume_seller_activation_email(current_setting('test.ticket'),'wrong@example.test'),null::jsonb,'capability is recipient-bound');
select is(consume_seller_activation_email(current_setting('test.ticket'),'branded@example.test')->>'subject','Welcome to Synthetic store','hook reads frozen personalized subject');
select is(consume_seller_activation_email(current_setting('test.ticket'),'branded@example.test'),null::jsonb,'consumed ticket cannot deliver twice');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"a2000000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.expired',gen_random_uuid()::text,true);
select queue_seller_communication(current_setting('test.tenant')::uuid,current_setting('test.expired')::uuid,current_setting('test.seller')::uuid,'message','seller.welcome','v3','sv','Expired','Frozen','none',null);
select set_config('test.oldticket',prepare_seller_activation_email(current_setting('test.tenant')::uuid,current_setting('test.expired')::uuid,'branded@example.test'),true);
reset role;
select set_config('komisio.communication_delivery','engine',true);
update seller_communications set activation_claimed_at=now()-interval '6 minutes' where id=current_setting('test.expired')::uuid;
select set_config('komisio.communication_delivery','',true);
set local role anon;
select is(consume_seller_activation_email(current_setting('test.oldticket'),'branded@example.test'),null::jsonb,'expired ticket cannot read or send');
select * from finish();
rollback;
